import { createClient } from "redis";

export function createRedis(url: string) {
  const redis = createClient({
    url,
    disableOfflineQueue: true,
    socket: { connectTimeout: 1_000 },
  });
  redis.on("error", (err: Error) => console.error(`redis: ${err.message}`));
  return redis;
}

export type Redis = ReturnType<typeof createRedis>;

import type { Redis } from "../../db/redis.ts";
import type { Availability, AvailabilityRepository } from "./availability.repository.ts";

const TTL_SECONDS = 60;

export const availabilityKey = (roomId: number, date: string) =>
  `roombook:availability:${roomId}:${date}`;

export function createAvailabilityService(redis: Redis, repo: AvailabilityRepository) {
  return {
    async get(roomId: number, date: string): Promise<Availability> {
      const key = availabilityKey(roomId, date);
      const cached = await redis.get(key).catch((err: Error) => {
        console.warn(`cache read failed for ${key}: ${err.message}`);
        return null;
      });
      if (cached !== null) return JSON.parse(cached) as Availability;

      const fresh = await repo.compute(roomId, date);
      await redis
        .set(key, JSON.stringify(fresh), { expiration: { type: "EX", value: TTL_SECONDS } })
        .catch((err: Error) => console.warn(`cache write failed for ${key}: ${err.message}`));
      return fresh;
    },
  };
}

import type { Redis } from "../../db/redis.ts";
import type { Availability, AvailabilityRepository } from "./availability.repository.ts";

const TTL_SECONDS = 60;

export const availabilityKey = (roomId: number, date: string) =>
  `roombook:availability:${roomId}:${date}`;

export function createAvailabilityService(redis: Redis, repo: AvailabilityRepository) {
  const inFlight = new Map<string, Promise<Availability>>();

  async function load(key: string, roomId: number, date: string) {
    const fresh = await repo.compute(roomId, date);
    const ttl = TTL_SECONDS + Math.floor(Math.random() * 10);
    await redis
      .set(key, JSON.stringify(fresh), { expiration: { type: "EX", value: ttl } })
      .catch((err: Error) => console.warn(`cache write failed for ${key}: ${err.message}`));
    return fresh;
  }

  return {
    async get(roomId: number, date: string): Promise<Availability> {
      const key = availabilityKey(roomId, date);
      const cached = await redis.get(key).catch(() => null);
      if (cached !== null) return JSON.parse(cached) as Availability;

      let pending = inFlight.get(key);
      if (!pending) {
        pending = load(key, roomId, date).finally(() => inFlight.delete(key));
        inFlight.set(key, pending);
      }
      return pending;
    },

    async invalidate(roomId: number, date: string): Promise<void> {
      await redis.del(availabilityKey(roomId, date));
    },
  };
}

import { ConflictError } from "../../domain/errors.ts";
import { localDate } from "../../lib/time.ts";
import type { createAvailabilityService } from "../rooms/availability.service.ts";
import type { Booking, NewBooking } from "./bookings.model.ts";
import type { InTransaction } from "./deps.ts";

type Deps = {
  inTransaction: InTransaction;
  availability: ReturnType<typeof createAvailabilityService>;
  clock: () => Date;
};

export function createBookingService(deps: Deps) {
  return {
    async create(input: NewBooking): Promise<Booking> {
      return deps.inTransaction(async ({ bookings, afterCommit }) => {
        const upcoming = await bookings.countUpcoming(input.userId, deps.clock());
        if (upcoming >= 3) {
          throw new ConflictError("booking-limit", "You already have 3 upcoming bookings.");
        }
        const booking = await bookings.insert(input);
        afterCommit(() => deps.availability.invalidate(booking.roomId, localDate(booking.startsAt)));
        return booking;
      });
    },
  };
}

import session from "express-session";
import { RedisStore } from "connect-redis";
import type { Redis } from "../../db/redis.ts";

export function sessions(redis: Redis, secret: string, production: boolean) {
  const cookie = sessionCookie(production);
  return session({
    name: cookie.name,
    cookie: cookie.options,
    secret,
    store: new RedisStore({ client: redis, prefix: "roombook:session:" }),
    resave: false,
    saveUninitialized: false,
    rolling: true,
  });
}

import { rateLimit } from "express-rate-limit";
import { RedisStore } from "rate-limit-redis";
import type { Redis } from "../../db/redis.ts";

export function loginLimiter(redis: Redis) {
  return rateLimit({
    windowMs: 15 * 60 * 1000,
    limit: 10,
    standardHeaders: "draft-8",
    legacyHeaders: false,
    store: new RedisStore({
      prefix: "roombook:rl:login:",
      sendCommand: (...args: string[]) => redis.sendCommand(args),
    }),
    handler: (req, res, _next, options) => {
      res.status(options.statusCode).type("application/problem+json").json({
        type: "https://roombook.example/problems/rate-limited",
        title: "Too many requests",
        status: options.statusCode,
        detail: "Too many login attempts. Try again later.",
        instance: req.originalUrl,
        requestId: res.locals.requestId,
      });
    },
  });
}

import express from "express";
import type { AddressInfo } from "node:net";
import { rateLimit } from "express-rate-limit";
import { dump } from "./dump.ts";

const app = express();
app.use((_req, res, next) => {
  res.locals.requestId = "req-7f3a9c2e"; // the request id middleware, fixed for the demo
  next();
});
app.post(
  "/v1/auth/login",
  rateLimit({
    windowMs: 15 * 60 * 1000,
    limit: 3,
    standardHeaders: "draft-8",
    legacyHeaders: false,
    handler: (req, res, _next, options) => {
      res.status(options.statusCode).type("application/problem+json").json({
        type: "https://roombook.example/problems/rate-limited",
        title: "Too many requests",
        status: options.statusCode,
        detail: "Too many login attempts. Try again later.",
        instance: req.originalUrl,
        requestId: res.locals.requestId,
      });
    },
  }),
  (_req, res) => {
    res.status(401).json({ type: "https://roombook.example/problems/unauthorized", title: "Unauthorized", status: 401 });
  },
);
const server = app.listen(0, "127.0.0.1", async () => {
  const { port } = server.address() as AddressInfo;
  const url = `http://127.0.0.1:${port}/v1/auth/login`;
  const body = JSON.stringify({ email: "ada@example.edu", password: "wrong" });
  for (let i = 1; i <= 3; i++) {
