  }
  console.log("attempt 4:");
  console.log(await dump(url, { method: "POST", body }));
  server.close();
});

import { createRedis } from "./db/redis.ts";
import { sendBookingConfirmation } from "./modules/bookings/emails.ts";

const STREAM = "roombook:jobs:email";
const GROUP = "email";
const consumer = `worker-${process.pid}`;

const redis = createRedis(process.env.REDIS_URL ?? "redis://localhost:6379");
await redis.connect();

try {
  await redis.xGroupCreate(STREAM, GROUP, "0", { MKSTREAM: true });
} catch (err) {
  if (!(err instanceof Error && err.message.startsWith("BUSYGROUP"))) throw err;
}

let running = true;
process.once("SIGTERM", () => (running = false));

while (running) {
  const batches = await redis.xReadGroup(GROUP, consumer, { key: STREAM, id: ">" }, { COUNT: 10, BLOCK: 5_000 });
  for (const { messages } of batches ?? []) {
    for (const { id, message } of messages) {
      try {
        await sendBookingConfirmation(Number(message.bookingId));
        await redis.xAck(STREAM, GROUP, id);
      } catch (err) {
        console.error(`job ${id} failed, it stays pending:`, err);
      }
    }
  }
}
await redis.close();

import { Router } from "express";
import type { Redis } from "../../db/redis.ts";

export const roomChannel = (roomId: number) => `roombook:rooms:${roomId}:events`;

export function roomEventsRouter(subscriber: Redis) {
  const router = Router();

  router.get("/:roomId/events", async (req, res) => {
    const channel = roomChannel(Number(req.params.roomId));
    res.set({ "Content-Type": "text/event-stream", "Cache-Control": "no-store" });
    res.flushHeaders();
    res.write("retry: 5000\n\n");

    const send = (message: string) => {
      const { id, data } = JSON.parse(message) as { id: number; data: unknown };
      res.write(`id: ${id}\nevent: availability\ndata: ${JSON.stringify(data)}\n\n`);
    };
    await subscriber.subscribe(channel, send);

    res.on("close", () => {
      subscriber.unsubscribe(channel, send).catch(() => {});
    });
  });

  return router;
}
